/**
 * Plugin Market — host half.
 *
 * Serves the embedded catalogue over HTTP so the browser half can render it.
 * The catalogue is generated by the collector (`export_panel_data.py`) and
 * shipped inside the package under `data/catalog.json`, so the panel works
 * offline and needs no API key.
 *
 * Routes (all exact):
 *   GET /api/plugin-market/list       catalogue, with optional q/category/only filters
 *   GET /api/plugin-market/item?id=   one entry, including its capability list
 *   GET /api/plugin-market/meta       counts, categories and data timestamp
 *   GET /api/plugin-market/catalog    raw catalogue passthrough
 *
 * Only metadata that the upstream registries publish is served. Nothing here
 * executes, installs or downloads package code.
 *
 * @module chongk-plugin-market
 */
import { readFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import Schema from '@deepseek-ai/schemastery'

const HERE = dirname(fileURLToPath(import.meta.url))

/** Loader-facing plugin name. */
export const name = 'plugin-market'

/** The web server owns route registration; without it this plugin stays idle. */
export const inject = ['webServer']

/** Panel configuration. */
export const Config = Schema.object({
  catalog: Schema.string()
    .default('')
    .description('Optional http(s) URL of a catalogue to fetch instead of the bundled one.'),
  pageSize: Schema.natural()
    .default(60)
    .description('Maximum entries returned by one list call.'),
})

const ROUTES = {
  list: '/api/plugin-market/list',
  item: '/api/plugin-market/item',
  meta: '/api/plugin-market/meta',
  catalog: '/api/plugin-market/catalog',
}

let cached = null

/**
 * Read the catalogue, preferring the configured URL over the bundled file.
 * @param config - resolved panel configuration.
 * @returns the parsed catalogue.
 */
async function loadCatalog(config) {
  const override = (config?.catalog ?? '').trim()
  if (override.startsWith('http://') || override.startsWith('https://')) {
    const response = await fetch(override)
    if (!response.ok) throw new Error(`catalogue fetch failed: HTTP ${response.status}`)
    return await response.json()
  }
  if (cached !== null) return cached
  const raw = await readFile(join(HERE, '..', 'data', 'catalog.json'), 'utf8')
  cached = JSON.parse(raw)
  return cached
}

/**
 * Write a JSON response, owning the full response lifecycle.
 * @param response - the server response.
 * @param status - HTTP status code.
 * @param body - value to serialise.
 */
function writeJson(response, status, body) {
  const text = JSON.stringify(body)
  response.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store',
    'content-length': Buffer.byteLength(text),
  })
  response.end(text)
}

/**
 * Reject a request whose method does not match, answering 405 itself.
 * @param request - the incoming request.
 * @param response - the server response.
 * @param method - the single accepted method.
 * @returns true when the caller may proceed.
 */
function guard(request, response, method) {
  if (request.method === method) return true
  writeJson(response, 405, { error: `method not allowed: ${request.method}` })
  return false
}

/**
 * Narrow the catalogue by the filters the panel sends.
 * @param items - catalogue entries.
 * @param query - parsed query string.
 * @returns the matching entries.
 */
function filterItems(items, query) {
  const text = (query.get('q') ?? '').trim().toLowerCase()
  const category = (query.get('category') ?? '').trim()
  const only = (query.get('only') ?? '').trim()

  let out = items
  if (category !== '') out = out.filter((item) => item.category === category)
  if (only === 'installable') out = out.filter((item) => item.installable)
  else if (only === 'client') out = out.filter((item) => item.client)
  else if (only === 'clean') out = out.filter((item) => item.capabilitySummary === 'none' || item.capabilitySummary === 'minimal')
  if (text !== '') {
    out = out.filter((item) => (
      item.name.toLowerCase().includes(text)
      || item.title.toLowerCase().includes(text)
      || item.description.toLowerCase().includes(text)
      || (item.keywords ?? []).some((keyword) => String(keyword).toLowerCase().includes(text))
    ))
  }
  return out
}

/**
 * Build the route table.
 * @param ctx - the plugin context.
 * @param config - resolved configuration.
 * @returns the route descriptors for `ctx.webServer.register`.
 */
function makeRoutes(ctx, config) {
  const warn = (error) => {
    try {
      ctx.logger?.warn?.(error)
    } catch {
      // a logging failure must never break a request
    }
  }

  return [
    {
      kind: 'exact',
      path: ROUTES.list,
      handler: async (request, response) => {
        if (!guard(request, response, 'GET')) return
        try {
          const catalog = await loadCatalog(config)
          const url = new URL(request.url ?? '/', 'http://localhost')
          const matched = filterItems(catalog.items ?? [], url.searchParams)
          const limit = Math.min(
            Number(url.searchParams.get('limit') ?? config.pageSize) || config.pageSize,
            config.pageSize,
          )
          const offset = Math.max(Number(url.searchParams.get('offset') ?? 0) || 0, 0)
          writeJson(response, 200, {
            total: catalog.total ?? matched.length,
            matched: matched.length,
            offset,
            limit,
            generatedAt: catalog.generatedAt ?? '',
            items: matched.slice(offset, offset + limit),
          })
        } catch (error) {
          warn(error)
          writeJson(response, 500, { error: String(error?.message ?? error) })
        }
      },
    },
    {
      kind: 'exact',
      path: ROUTES.item,
      handler: async (request, response) => {
        if (!guard(request, response, 'GET')) return
        try {
          const url = new URL(request.url ?? '/', 'http://localhost')
          const id = (url.searchParams.get('id') ?? '').trim()
          if (id === '') {
            writeJson(response, 400, { error: 'missing id' })
            return
          }
          const catalog = await loadCatalog(config)
          const item = (catalog.items ?? []).find((candidate) => candidate.id === id || candidate.name === id)
          if (item === undefined) {
            writeJson(response, 404, { error: `plugin not found: ${id}` })
            return
          }
          writeJson(response, 200, { item })
        } catch (error) {
          warn(error)
          writeJson(response, 500, { error: String(error?.message ?? error) })
        }
      },
    },
    {
      kind: 'exact',
      path: ROUTES.meta,
      handler: async (request, response) => {
        if (!guard(request, response, 'GET')) return
        try {
          const catalog = await loadCatalog(config)
          const items = catalog.items ?? []
          writeJson(response, 200, {
            total: catalog.total ?? items.length,
            generatedAt: catalog.generatedAt ?? '',
            categories: catalog.categories ?? {},
            installable: items.filter((item) => item.installable).length,
            client: items.filter((item) => item.client).length,
            scanned: items.filter((item) => item.capabilitySummary !== '').length,
            // Counted from the items rather than trusting the catalogue's own
            // tally, so the two cannot disagree if one is written without the
            // other. `runtimeVersion` says which DSH build the verdicts are for.
            runtimeIncompatible: items.filter((item) => item.runtimeCompatible === false).length,
            runtimeVersion: catalog.runtimeVersion ?? '',
            upstreamGone: items.filter((item) => item.upstreamGone === true).length,
          })
        } catch (error) {
          warn(error)
          writeJson(response, 500, { error: String(error?.message ?? error) })
        }
      },
    },
    {
      kind: 'exact',
      path: ROUTES.catalog,
      handler: async (request, response) => {
        if (!guard(request, response, 'GET')) return
        try {
          writeJson(response, 200, await loadCatalog(config))
        } catch (error) {
          warn(error)
          writeJson(response, 500, { error: String(error?.message ?? error) })
        }
      },
    },
  ]
}

/**
 * Plugin body. Routes are registered inside `ctx.effect`, so unloading the
 * plugin removes every route it claimed.
 * @param ctx - the plugin's own context.
 * @param config - the resolved configuration for this entry.
 */
export function apply(ctx, config) {
  ctx.effect(() => {
    const disposers = makeRoutes(ctx, config).map((route) => ctx.webServer.register(route))
    return () => {
      for (const dispose of disposers) dispose()
    }
  }, 'plugin-market: routes')
}
